1	#pragma once
2	
3	#include <chrono>
4	#include <functional>
5	#include <cstdint>
6	#include <string>
7	#include <unordered_map>
8	#include <vector>
9	
10	namespace amr_dispatcher_core::workflow {
11	
12	// 时空窗交通协调（Task B）：把"静态排他锁"升级为"带时间窗的预约"。
13	//
14	// 安全模型（评审要求）：
15	//   1. **逐资源区间**：一条路径涉及多个资源（边=通道、节点=路口），
16	//      每个资源单独计算进入/离开时刻。路口窗口 = 进入路口到驶出路口的完整区间。
17	//   2. **全有或全无**：整条路径的预约必须**全部成功**才提交；任一资源失败
18	//      则全部回滚，不留半套预约。
19	//   3. **窗口到期 ≠ 资源已释放**：物理资源仍需车辆确认驶离（lastNodeId 推进，
20	//      见 Spec §5.3 逐段解锁）才可让后车进入。延期靠 ExtendTimeSpace，
21	//      绝不靠"到点自动失效"。
22	//   4. **安全余量**：占用时长含加减速/转弯附加时间与车辆尺寸安全余量。
23	//
24	// 本模块只做**决策**（纯函数、零 ROS）；预约表的落地由 ResourceTable 承担。
25	
26	// 单个资源的时间占用区间。
27	struct ResourceTimeWindow {
28	  std::string resource_id;   // route_edge:A__B 或 route_node:A
29	  std::chrono::steady_clock::time_point enter;
30	  std::chrono::steady_clock::time_point exit;
31	  // 该资源是"通道"（边）还是"路口"（节点）——路口的冲突判定更严格
32	  // （对向/交叉车辆的物理冲突发生在路口内部）。
33	  bool is_intersection = false;
34	};
35	
36	// 路径占用区间集合（一个 mission 的全部资源）。
37	using ResourceTimeWindowSet = std::vector<ResourceTimeWindow>;
38	
39	// 车辆运动参数（用于把几何长度换算成时间占用）。
40	struct MotionTimingConfig {
41	  // 巡航速度（m/s）。
42	  double cruise_speed_mps = 1.0;
43	  // 起步/刹停附加时间（秒）——每次进入资源都要付。
44	  double accel_overhead_sec = 1.0;
45	  // 转弯附加时间（秒）——按路径拐点数计。
46	  double turn_overhead_sec = 0.5;
47	  // 车辆尺寸安全余量（米）——沿路径方向额外占用长度。
48	  double safety_margin_m = 0.2;
49	  // 最小安全间隔（秒）：后车进入同一资源前必须与前车拉开该间隔。
50	  double min_headway_sec = 2.0;
51	};
52	
53	// 单个候选任务的输入。
54	struct TimeSpaceCandidate {
55	  std::string mission_id;
56	  // 该单的行驶路径（节点序列，行驶序）。
57	  std::vector<std::string> path_node_ids;
58	  // 路径中每段的折线长度（米），与 path_node_ids 的相邻对一一对应：
59	  // lengths[i] 对应 path_node_ids[i] -> path_node_ids[i+1]。
60	  std::vector<double> segment_lengths_m;
61	  // 该单的最早可开始时刻。
62	  std::chrono::steady_clock::time_point earliest_start;
63	  // 资源 id 构造器（由调用方注入，核心不直接依赖 dispatcher 层）：
64	  // 边 id = f(from, to)，节点 id = g(node)。
65	  std::function<std::string(const std::string&, const std::string&)> edge_id_builder;
66	  std::function<std::string(const std::string&)> node_id_builder;
67	  // 期望时长（秒）：优先用它替代按长度估算（业务给的更准）。
68	  int expected_seconds = 0;
69	};
70	
71	// 冲突检测结果（对一次预约尝试）。
72	struct TimeSpaceConflict {
73	  bool has_conflict = false;
74	  std::string resource_id;
75	  std::string conflicting_mission_id;
76	  // 冲突原因：headway（安全间隔不足）/ overlap（区间重叠）
77	  std::string reason;
78	  // 建议后移的时长（秒）。
79	  double suggested_delay_sec = 0.0;
80	};
81	
82	// 一单的预约决策结果。
83	struct TimeSpacePlan {
84	  bool feasible = false;
85	  std::string reject_reason;
86	  // 每条资源最终占用的区间（可能整体后移）。
87	  ResourceTimeWindowSet windows;
88	  // 整体后移的时长（秒）。
89	  double total_delay_sec = 0.0;
90	  // 冲突诊断（供可观测与调度重排）。
91	  std::vector<TimeSpaceConflict> conflicts;
92	};
93	
94	// 已占用区间表：resource_id -> 区间列表（含 mission 与安全间隔）。
95	struct TimeSpaceOccupancy {
96	  struct Entry {
97	    std::string mission_id;
98	    std::chrono::steady_clock::time_point enter;
99	    std::chrono::steady_clock::time_point exit;
100	    bool is_intersection = false;
101	  };
102	  std::unordered_map<std::string, std::vector<Entry>> by_resource;
103	};
104	
105	// 纯函数：为一个候选任务规划时间窗。
106	//   1. 按 MotionTimingConfig 把路径换算成逐资源区间（含加减速/转弯/安全余量）。
107	//   2. 与 occupancy 比对：区间重叠 或 后车进入早于前车离开 + min_headway -> 冲突。
108	//   3. 冲突时整体后移到最早可行时刻（最多重试 occupancy.size()+1 次），
109	//      仍冲突 -> feasible=false。
110	//   4. 成功时返回各资源的最终窗口（调用方负责写回 occupancy）。
111	TimeSpacePlan PlanTimeSpaceReservation(const TimeSpaceCandidate& candidate,
112	                                       const TimeSpaceOccupancy& occupancy,
113	                                       const MotionTimingConfig& config);
114	
115	// 把一个已确认的时间窗集合并入占用表（调用方在整条路径预约成功后调用）。
116	void CommitTimeSpaceOccupancy(TimeSpaceOccupancy* occupancy, const std::string& mission_id,
117	                               const ResourceTimeWindowSet& windows);
118	
119	// 逐资源释放某任务的占用区间（车辆**确认驶离**该资源后调用）。
120	//   * 只释放该任务在该资源上的区间（owner 校验），他人区间不动；
121	//   * 该资源上该任务没有区间 -> 幂等 no-op（返回 false 但不改表）。
122	// 评审 B.2 的关键：**窗口到期 ≠ 资源已释放**——到期只意味着"计划上应该走了"，
123	// 物理释放必须由确认驶离驱动，否则后车会在前车还在时进入。
124	bool ReleaseTimeSpaceResources(TimeSpaceOccupancy* occupancy, const std::string& mission_id,
125	                               const std::vector<std::string>& resource_ids,
126	                               std::vector<std::string>* released_resource_ids);
127	
128	// 某任务在某资源上是否仍持有占用区间。
129	bool HoldsTimeSpaceResource(const TimeSpaceOccupancy& occupancy, const std::string& mission_id,
130	                             const std::string& resource_id);
131	
132	// 车辆执行滞后时延长其占用窗口（评审 B.2：窗口到期不能单独作为释放依据）。
133	// 延长失败（与后车窗口冲突）时返回 false，由调度层让后车等待。
134	bool ExtendTimeSpaceOccupancy(TimeSpaceOccupancy* occupancy, const std::string& mission_id,
135	                               const std::chrono::steady_clock::time_point& new_exit,
136	                               std::string* message);
137	
138	}  // namespace amr_dispatcher_core::workflow
139

