127	    start.resource_id = candidate.node_id_builder(candidate.path_node_ids.front());
128	    start.enter = candidate.earliest_start;
129	    start.exit = candidate.earliest_start + FromSeconds(config.accel_overhead_sec);
130	    start.is_intersection = true;
131	    base_windows.push_back(start);
