196	    entry.mission_id = mission_id;
197	    entry.enter = window.enter;
198	    entry.exit = window.exit;
199	    entry.is_intersection = window.is_intersection;
200	    occupancy->by_resource[window.resource_id].push_back(entry);
201	  }
202	}
