204	bool ReleaseTimeSpaceResources(TimeSpaceOccupancy* occupancy, const std::string& mission_id,
205	                               const std::vector<std::string>& resource_ids,
206	                               std::vector<std::string>* released_resource_ids) {
207	  if (occupancy == nullptr) {
208	    return false;
209	  }
210	  bool any = false;
211	  for (const auto& resource_id : resource_ids) {
212	    const auto it = occupancy->by_resource.find(resource_id);
213	    if (it == occupancy->by_resource.end()) {
214	      continue;
215	    }
216	    auto& entries = it->second;
217	    const std::size_t before = entries.size();
218	    entries.erase(std::remove_if(entries.begin(), entries.end(),
219	                                  [&mission_id](const TimeSpaceOccupancy::Entry& e) {
220	                                    return e.mission_id == mission_id;
221	                                  }),
222	                  entries.end());
223	    if (entries.size() != before) {
224	      any = true;
225	      if (released_resource_ids != nullptr) {
226	        released_resource_ids->push_back(resource_id);
227	      }
228	    }
229	    if (entries.empty()) {
230	      occupancy->by_resource.erase(it);
231	    }
232	  }
233	  return any;
234	}
