236	bool HoldsTimeSpaceResource(const TimeSpaceOccupancy& occupancy, const std::string& mission_id,
237	                             const std::string& resource_id) {
238	  const auto it = occupancy.by_resource.find(resource_id);
239	  if (it == occupancy.by_resource.end()) {
240	    return false;
241	  }
242	  for (const auto& entry : it->second) {
243	    if (entry.mission_id == mission_id) {
244	      return true;
245	    }
246	  }
247	  return false;
248	}
249	
250	bool ExtendTimeSpaceOccupancy(TimeSpaceOccupancy* occupancy, const std::string& mission_id,
251	                               const Clock::time_point& new_exit, std::string* message) {
252	  if (occupancy == nullptr) {
253	    if (message != nullptr) *message = "occupancy is null";
254	    return false;
255	  }
256	  // 先验证延长后是否与他车窗口冲突（不满足则不改动占用表）。
257	  for (const auto& [resource_id, entries] : occupancy->by_resource) {
258	    for (const auto& entry : entries) {
259	      if (entry.mission_id != mission_id) {
260	        continue;
261	      }
262	      if (new_exit <= entry.exit) {
263	        continue;  // 未延长
264	      }
265	      // 与该资源上其他车辆的窗口比对
266	      for (const auto& other : entries) {
267	        if (other.mission_id == mission_id) continue;
268	        if (other.enter < new_exit && entry.enter < other.exit) {
269	          if (message != nullptr) {
270	            *message = "extension conflicts with mission " + other.mission_id + " on " +
271	                       resource_id;
272	          }
273	          return false;
274	        }
275	      }
276	    }
277	  }
278	  // 无冲突：执行延长
279	  for (auto& [resource_id, entries] : occupancy->by_resource) {
280	    for (auto& entry : entries) {
281	      if (entry.mission_id == mission_id && new_exit > entry.exit) {
282	        entry.exit = new_exit;
283	      }
284	    }
285	  }
286	  if (message != nullptr) *message = "time window extended";
287	  return true;
288	}
289	
290	}  // namespace amr_dispatcher_core::workflow
